var i=`1221-ropa-vieja-panamanian-style`;var a=`world-1221`;var t=`PA`;var s=`central-america-caribbean`;var o=4;var r=162;var l={en:`Ropa Vieja Panamanian Style`,ua:`Ропа в'єха по-панамськи`};var d={en:`Ropa Vieja Panamanian Style is a dish from Panama featuring beef flank steak, yellow onion, garlic, bay leaf. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Ропа в'єха по-панамськи, страва кухні країни Панама з такими основними складниками: яловичий фланк-стейк, жовта цибуля, часник, лавровий лист. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var g=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`beef-flank-steak`,850,`g`],[`canola-oil`,35,`ml`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 115 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 115 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:115,i:[[`beef-stock`,900,`ml`],[`yellow-onion`,180,`g`],[`garlic`,5,`clove`],[`bay-leaf`,2,`leaf`]]},{en:`Shred the fully cooked meat into thin pieces with clean forks, discarding bones and tough connective tissue.`,ua:`Розберіть повністю приготоване м’ясо чистими виделками на тонкі волокна, видаливши кістки й жорсткі частини.`,t:[`shredding`,`mixing`],m:12,i:[]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 20 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 20 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:20,i:[[`tomato`,420,`g`],[`red-bell-pepper`,220,`g`],[`ground-cumin`,5,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,25,`g`]]}];var m={slug:i,id:a,country:`PA`,region:s,servings:4,minutes:162,title:l,text:d,steps:g};export{t as country,m as default,a as id,r as minutes,s as region,o as servings,i as slug,g as steps,d as text,l as title};